run=PROJECT_ROOT/'runs/20261106_v7_other_unresolved_review_v1';name=os.environ['REVIEW_LINEAGE'];d=run/('stage_d_'+name+'_refit');assert json.loads((run/'launch'/(name+'_refit_terminal.json')).read_text())['exit_code']==0;o=run/('stage_e_'+name+'_marker_review');o.mkdir(exist_ok=False);policy=json.loads((run/'review_policy_v1.json').read_text());extra=['IGKC','IGLC2','IGLC3','IGHG1','IGHG3','IGHA1','IGHM','CHGA','CHGB','SYP','PCSK1N','CPE','FXYD2','MGP','IFI27','MAPT','NEFL','NEFM','NCAM1','TACC2','CACNA1A'];genes=list(dict.fromkeys(policy['genes']+extra))
