 t=q.iloc[np.flatnonzero(cl==c)];z={'cluster':c,'n_cells':len(t),'n_sources':t.gse_id.nunique(),'max_source_fraction':float(t.gse_id.astype(str).value_counts().iloc[0]/len(t)),'decontx_median':float(pd.to_numeric(t.decontx_contamination,errors='coerce').median()),'raw_library_median':float(t.full_raw_library_total.median()),'original_doublet_percentile_median':float(pd.to_numeric(t.doublet_within_sample_method_percentile,errors='coerce').median()),'n_external_candidates':int(t.recruitment_basis.ne('old_V7_candidate_parent').sum()),'dominant_old_label':str(t.final_annotation_v7.value_counts().index[0]),'dominant_old_label_fraction':float(t.final_annotation_v7.value_counts().iloc[0]/len(t))}
 for key in ['T_positive_source_aware','NK_receptor_effector_positive','B_distinct_components_positive','ASC_distinct_components_positive','Myeloid_mature_components_positive','Endothelial_distinct_components_positive','Epithelial_distinct_components_positive','Fibroblast_distinct_components_positive','Ery_structural_synthesis_nonHB_positive','Ery_nonHB_multigene_positive','Platelet_secreted_structural_positive','HSPC_primitive_components_positive','HSPC_hematopoietic_components_positive','ILC2_or_ILC3_specific_program_positive']:z['n_'+key]=int(t[key].sum())
